(() => {
  // Find checkboxes related to delete/trash
  const checks = [];
  document.querySelectorAll('input[type=checkbox], [role=checkbox]').forEach((el,i) => {
    const label = el.getAttribute('aria-label') || el.nextElementSibling?.textContent || el.parentElement?.textContent || '';
    const t = label.trim().slice(0,100);
    if (/삭제|휴지|Delete|Trash|받은편지|Inbox|일치|적용|읽음|중요|star/i.test(t)) {
      checks.push({i, t, checked: el.checked || el.getAttribute('aria-checked'), id: el.id, name: el.name});
    }
  });
  // Also look for nearby text of filter action panel
  const bodyText = Array.from(document.querySelectorAll('label, span, div')).filter(el => /삭제|일치하는/.test(el.textContent||'') && (el.textContent||'').length < 80).map(el => el.textContent.trim()).slice(0,40);
  return {checks: checks.slice(0,40), bodyText};
})()

(() => {
  const clickCheck = (id) => {
    const el = document.getElementById(id);
    if (!el) return {ok:false, id, reason:'not found'};
    // Gmail uses custom checkboxes; click the input or its label
    el.click();
    if (!el.checked) {
      el.checked = true;
      el.dispatchEvent(new Event('change', {bubbles:true}));
      el.dispatchEvent(new MouseEvent('click', {bubbles:true}));
    }
    return {ok:true, id, checked: el.checked};
  };
  const r1 = clickCheck(':1ng'); // 삭제
  const r2 = clickCheck(':2eb'); // 일치하는 대화에도 필터 적용
  return {r1, r2};
})()

(() => {
  // Find the create filter submit button (not the earlier search one)
  const buttons = Array.from(document.querySelectorAll('button, div[role=button], input[type=submit]'));
  const candidates = buttons.map(b => ({
    text: (b.innerText||b.value||'').trim(),
    cls: (b.className||'').toString().slice(0,80),
    disabled: b.disabled || b.getAttribute('aria-disabled')
  })).filter(b => /필터 만들기|Create filter|필터 생성/.test(b.text));
  // Prefer the one in a dialog/modal area - often last matching
  const createBtns = buttons.filter(b => /^\s*필터 만들기\s*$/.test((b.innerText||'').trim()) || /^\s*Create filter\s*$/.test((b.innerText||'').trim()));
  if (createBtns.length === 0) return {error:'no button', candidates};
  const btn = createBtns[createBtns.length-1];
  btn.click();
  return {clicked: (btn.innerText||'').trim(), count: createBtns.length, candidates};
})()

