async function createTrashFilter(fromValue) {
  // Navigate via hash search
  location.hash = '#search/from%3A' + encodeURIComponent(fromValue);
  await new Promise(r => setTimeout(r, 2500));
  // Open advanced search by clicking 고급검색 if present
  const adv = Array.from(document.querySelectorAll('button')).find(b => (b.innerText||'').includes('고급검색'));
  if (adv) { adv.click(); await new Promise(r => setTimeout(r, 1000)); }
  // Click 필터 만들기
  let create = Array.from(document.querySelectorAll('button')).find(b => (b.innerText||'').trim() === '필터 만들기');
  if (!create) return {ok:false, step:'no create button', fromValue};
  create.click();
  await new Promise(r => setTimeout(r, 1500));
  // Check 삭제 and 일치하는 대화에도
  const checks = Array.from(document.querySelectorAll('input[type=checkbox]'));
  let deleted=false, applied=false;
  for (const el of checks) {
    const t = (el.getAttribute('aria-label') || el.parentElement?.textContent || '').trim();
    if (t === '삭제' || t.startsWith('삭제')) { if (!el.checked) el.click(); deleted = el.checked; }
    if (t.includes('일치하는')) { if (!el.checked) el.click(); applied = el.checked; }
  }
  // Also try by id scan of visible checkboxes near those labels
  document.querySelectorAll('label, span').forEach(span => {
    const t = (span.textContent||'').trim();
    if (t === '삭제') {
      const inp = span.closest('label')?.querySelector('input') || span.previousElementSibling || span.parentElement?.querySelector('input');
      if (inp && !inp.checked) inp.click();
    }
    if (t.includes('일치하는') && t.includes('적용')) {
      const inp = span.closest('label')?.querySelector('input') || span.previousElementSibling || span.parentElement?.querySelector('input');
      if (inp && !inp.checked) inp.click();
    }
  });
  await new Promise(r => setTimeout(r, 300));
  // Submit - last 필터 만들기 button
  const btns = Array.from(document.querySelectorAll('button')).filter(b => (b.innerText||'').trim() === '필터 만들기');
  if (btns.length) btns[btns.length-1].click();
  await new Promise(r => setTimeout(r, 3000));
  return {ok:true, fromValue, deleted, applied, createBtns: btns.length};
}
