(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  // dismiss error if present
  const okBtn = Array.from(document.querySelectorAll('button')).find(b => (b.innerText||'').trim() === '확인');
  if (okBtn) { okBtn.click(); await sleep(500); }
  const del = document.querySelector('[aria-label="삭제"]');
  const apply = Array.from(document.querySelectorAll('[aria-label]')).find(e => (e.getAttribute('aria-label')||'').includes('일치하는'));
  const ensureOn = (el) => {
    if (!el) return null;
    const state = el.getAttribute('aria-checked');
    if (state === 'false' || state === null) el.click();
    // click again if still false
    if (el.getAttribute('aria-checked') === 'false') el.click();
    return el.getAttribute('aria-checked');
  };
  const delState = ensureOn(del);
  const applyState = ensureOn(apply);
  await sleep(300);
  const btns = Array.from(document.querySelectorAll('button')).filter(b => (b.innerText||'').trim() === '필터 만들기');
  if (btns.length) btns[btns.length-1].click();
  await sleep(3500);
  const err = Array.from(document.querySelectorAll('h2')).find(h => (h.textContent||'').includes('필터 생성 오류'));
  return {
    delState, applyState,
    applyLabel: apply?.getAttribute('aria-label'),
    createClicked: btns.length,
    error: err ? 'still error' : 'no error heading'
  };
})()

