  await sleep(4000);
  const err = document.body.innerText.includes('수행할 작업을 하나 이상');
  const inboxLeft = null;
  return {map: map.filter(m => /삭제|일치|건너뛰|읽음|중요|스팸/.test(m.parentText||'')), del, apply, delOk, applyOk, err};
})()

(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  // dismiss error
  const ok = Array.from(document.querySelectorAll('button')).find(b => (b.innerText||'').trim() === '확인');
  if (ok) { ok.click(); await sleep(600); }
  const forceCheck = (id) => {
    const el = document.getElementById(id);
    if (!el) return 'missing';
    el.focus();
    // click label if any
    const label = el.closest('label') || document.querySelector(`label[for="${CSS.escape(id)}"]`);
    if (label) label.click();
    el.click();
    el.checked = true;
    el.dispatchEvent(new MouseEvent('mousedown', {bubbles:true}));
    el.dispatchEvent(new MouseEvent('mouseup', {bubbles:true}));
    el.dispatchEvent(new MouseEvent('click', {bubbles:true}));
    el.dispatchEvent(new Event('input', {bubbles:true}));
    el.dispatchEvent(new Event('change', {bubbles:true}));
    return el.checked;
  };
  // re-find ids
  let delId=null, applyId=null;
  for (const el of document.querySelectorAll('input[type=checkbox]')) {
    const t = (el.closest('tr') || el.parentElement)?.textContent?.replace(/\s+/g,' ').trim();
    if (t === '삭제' || t?.startsWith('삭제 ')) delId = el.id;
    if (t?.includes('일치하는')) applyId = el.id;
  }
  const d = forceCheck(delId);
  const a = forceCheck(applyId);
  await sleep(500);
  const d2 = document.getElementById(delId)?.checked;
  const a2 = document.getElementById(applyId)?.checked;
  if (!d2 || !a2) return {ok:false, delId, applyId, d, a, d2, a2};
  const btns = Array.from(document.querySelectorAll('button')).filter(b => (b.innerText||'').trim() === '필터 만들기');
  btns[btns.length-1].click();
  await sleep(5000);
  return {
    ok:true, delId, applyId, d2, a2,
    err: document.body.innerText.includes('수행할 작업을 하나 이상'),
    successHint: document.body.innerText.includes('필터가 만들어') || !location.hash.includes('create-filter')
  };
})()

