from pathlib import Path
import re

root = Path("/Users/gimjongho/오소풍_wiki")
skip_names = {"AGENTS.md", "DESIGN-v2.md", "Home.md"}
skip_dirs = {".obsidian", "templates", "_archive", "inbox"}

changed = []
for path in root.rglob("*.md"):
    if any(p in skip_dirs for p in path.parts):
        continue
    if path.name in skip_names:
        continue
    text = path.read_text(encoding="utf-8")
    if "- [ ] 감수" not in text:
        continue
    if not text.startswith("---"):
        continue
    # already has draft cssclass?
    if re.search(r"(?m)^cssclasses:\s*\n(?:[ \t]*-[ \t]*.*\n)*[ \t]*-[ \t]*draft\s*$", text) or re.search(r"cssclasses:\s*\[([^\]]*draft[^\]]*)\]", text):
        continue
    m = re.match(r"^---\n(.*?)\n---\n", text, re.S)
    if not m:
        continue
    fm = m.group(1)
    if re.search(r"(?m)^status:\s*final\s*$", fm):
        continue
    # insert cssclasses after status or at end of frontmatter
    if re.search(r"(?m)^cssclasses:\s*$", fm) or re.search(r"(?m)^cssclasses:", fm):
        # append draft to list form
        if "draft" in fm.split("cssclasses", 1)[-1][:80]:
            continue
        fm2 = re.sub(r"(?m)^(cssclasses:\s*\n(?:[ \t]*-[ \t]*.*\n)*)", r"\1  - draft\n", fm, count=1)
        if fm2 == fm:
            fm2 = re.sub(r"(?m)^cssclasses:\s*\[([^\]]*)\]", lambda m: f"cssclasses: [{m.group(1).rstrip(', ')}, draft]" if "draft" not in m.group(1) else m.group(0), fm)
    else:
        if re.search(r"(?m)^status:\s*", fm):
            fm2 = re.sub(r"(?m)^(status:\s*.*\n)", r"\1cssclasses:\n  - draft\n", fm, count=1)
        else:
            fm2 = fm + "\ncssclasses:\n  - draft\n"
    new = text[:m.start(1)] + fm2 + text[m.end(1):]
    if new != text:
        path.write_text(new, encoding="utf-8")
        changed.append(str(path.relative_to(root)))

print(f"updated {len(changed)} files")
for c in changed:
    print(" -", c)
