from pathlib import Path
import re

root = Path('/Users/gimjongho/오소풍_wiki')
formalized = []
still_unreviewed = []

scan_dirs = [root/'library', root/'essays']
for base in scan_dirs:
    for p in base.rglob('*.md'):
        text = p.read_text(encoding='utf-8')
        has_checked = bool(re.search(r'- \[x\] 감수', text, re.I))
        has_unchecked = bool(re.search(r'- \[ \] 감수', text))
        has_draft_marker = '(초안)' in text
        fm = {}
        if text.startswith('---'):
            end = text.find('\n---', 3)
            if end != -1:
                block = text[3:end]
                m = re.search(r'^status:\s*(\w+)', block, re.M)
                if m:
                    fm['status'] = m.group(1)

        # formalize: [x] and (still draft status or has (초안) near 한 줄)
        if has_checked and (fm.get('status') == 'draft' or has_draft_marker):
            new = text
            # remove (초안) prefix on lines in 내 한 줄 section roughly - only leading (초안)
            new = re.sub(r'(?m)^(\(초안\)\s*)', '', new)
            if fm.get('status') == 'draft':
                new = re.sub(r'(?m)^status:\s*draft\s*$', 'status: final', new, count=1)
            if new != text:
                p.write_text(new, encoding='utf-8')
                formalized.append(str(p.relative_to(root)))

        text2 = p.read_text(encoding='utf-8')
        if re.search(r'- \[ \] 감수', text2):
            still_unreviewed.append(str(p.relative_to(root)))

# inbox unprocessed (except README, 헤르메스에게)
for p in (root/'inbox').glob('*.md'):
